explanation.text:
syntax = "proto3";

message UserEvent {
  int64  user_id        = 1;
  string email          = 2;
  string full_name      = 3;
  repeated string roles = 4;
  int64  created_at_ms  = 5;
}

struct UserEvent {
  1: required i64    user_id,
  2: required string email,
  3: optional string full_name,
  4: list<string>    roles,
  5: required i64    created_at_ms
}

service UserService {
  UserEvent getUser(1: i64 user_id)
  void      deleteUser(1: i64 user_id)
}

// v1 schema
message Order {
  int64  order_id = 1;
  string customer = 2;
}

// v2 schema — backward compatible: new optional field, tag 3
message Order {
  int64  order_id     = 1;
  string customer     = 2;
  string promo_code   = 3;  // absent in old messages; defaults to ""
}
